from __future__ import annotations

import json

from services.execution.gateway import BinanceUsdtPerpetualGateway
from shared.config import settings

ORDER_ID = "14240828026"


def main() -> None:
    if not settings.binance_use_testnet:
        print(json.dumps({"status": "blocked", "reason": "binance_use_testnet_false"}))
        return
    if not settings.binance_api_key or not settings.binance_api_secret:
        print(json.dumps({"status": "blocked", "reason": "credentials_not_configured"}))
        return
    try:
        gateway = BinanceUsdtPerpetualGateway(use_testnet=True)
        raw = gateway.client.fapiPrivateGetOrder({"symbol": "ETHUSDT", "orderId": ORDER_ID})
        allowed = (
            "orderId",
            "symbol",
            "side",
            "type",
            "status",
            "avgPrice",
            "executedQty",
            "reduceOnly",
            "time",
            "updateTime",
        )
        print(
            json.dumps(
                {
                    "status": "ok",
                    "api_backend": getattr(gateway, "api_backend", None),
                    "order": {key: raw.get(key) for key in allowed},
                }
            )
        )
    except Exception as exc:
        print(
            json.dumps(
                {
                    "status": "unavailable",
                    "exception_type": type(exc).__name__,
                    "error": str(exc),
                }
            )
        )


if __name__ == "__main__":
    main()

